package dev.cardadvisor.finance;
import dev.cardadvisor.api.ApiError;
import dev.cardadvisor.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import java.time.*;
import java.util.*;
@Service @Transactional public class ActualQualificationService {
 private final JdbcTemplate db;public ActualQualificationService(JdbcTemplate db){this.db=db;}
 public record Input(Long expectedVersion,Long expectedStateVersion,Long previousPerformanceWon,String previousSource,LocalDate asOf,LocalDate firstUseDate,Boolean confirmed){}
 private void lock(UUID u){if(db.queryForList("SELECT id FROM app_users WHERE id=? FOR UPDATE",u).isEmpty())throw new ApiError(401,"SESSION_EXPIRED");}
 private String rule(UUID u,UUID card){var rows=db.queryForList("SELECT payload->>'source' AS rule FROM cards WHERE user_id=? AND id=?",u,card);if(rows.isEmpty())throw new ApiError(404,"CARD_NOT_FOUND");String rule=(String)rows.get(0).get("rule");if(!ActualCardRules.actual(rule))throw new ApiError(422,"ACTUAL_CARD_REQUIRED");return rule;}
 private YearMonth month(String s){try{var month=YearMonth.parse(s);if(month.isAfter(YearMonth.now(ZoneId.of("Asia/Seoul"))))throw new IllegalArgumentException();return month;}catch(Exception e){throw new ApiError(422,"INVALID_QUALIFICATION_MONTH");}}
 private long stateVersion(UUID u,UUID c,YearMonth m){return db.queryForObject("SELECT COALESCE((SELECT version FROM card_month_states WHERE user_id=? AND card_id=? AND month=?),0)",Long.class,u,c,m.atDay(1));}
 public Map<String,Object> get(UUID u,UUID c,String period){lock(u);String rule=rule(u,c);var month=month(period);var rows=db.queryForList("SELECT * FROM actual_qualification_facts WHERE user_id=? AND card_id=? AND month=?",u,c,month.atDay(1));var s=rows.isEmpty()?null:rows.get(0);long version=stateVersion(u,c,month);var out=new LinkedHashMap<String,Object>();out.put("cardId",c);out.put("month",period);out.put("version",s==null?0:s.get("version"));out.put("stateVersion",version);out.put("previousPerformanceWon",s==null?null:s.get("previous_performance_won"));out.put("previousSource",s==null?"UNKNOWN":s.get("previous_source"));out.put("asOf",s==null?null:s.get("as_of"));out.put("firstUseDate",s==null?null:s.get("first_use_date"));out.put("current",s!=null&&((Number)s.get("qualification_version")).longValue()==version);out.put("ruleVersion",ActualQualification.VERSION);out.put("source","USER_CONFIRMED_TERMS_ESTIMATE");out.put("calculation",ActualQualification.calculate(rule,month,s==null?null:(Long)s.get("previous_performance_won"),s==null||s.get("first_use_date")==null?null:((java.sql.Date)s.get("first_use_date")).toLocalDate()));return out;}
 public Object save(UUID u,UUID c,String period,Input in){lock(u);String rule=rule(u,c);var m=month(period);var old=get(u,c,period);LocalDate today=LocalDate.now(ZoneId.of("Asia/Seoul"));
  if(in==null||in.expectedVersion()==null||in.expectedStateVersion()==null||!Boolean.TRUE.equals(in.confirmed())||in.previousSource()==null)throw new ApiError(422,"QUALIFICATION_CONFIRMATION_REQUIRED");
  if(in.expectedVersion()!=((Number)old.get("version")).longValue()||in.expectedStateVersion()!=((Number)old.get("stateVersion")).longValue())throw new ApiError(409,"QUALIFICATION_VERSION_CONFLICT");
  if(in.previousPerformanceWon()==null?(!in.previousSource().equals("UNKNOWN")||in.asOf()!=null):(!Set.of("USER_INPUT","USER_ESTIMATE").contains(in.previousSource())||in.asOf()==null||in.asOf().isBefore(m.minusMonths(1).atEndOfMonth())||in.asOf().isAfter(today)||in.asOf().isAfter(m.atEndOfMonth())))throw new ApiError(422,"INVALID_QUALIFICATION_EVIDENCE");
  if(in.firstUseDate()!=null&&(in.firstUseDate().isAfter(today)||in.firstUseDate().isAfter(m.atEndOfMonth())||in.firstUseDate().isBefore(LocalDate.of(1990,1,1))))throw new ApiError(422,"INVALID_FIRST_USE_DATE");
  ActualQualification.Result result;try{result=ActualQualification.calculate(rule,m,in.previousPerformanceWon(),in.firstUseDate());}catch(IllegalArgumentException e){throw new ApiError(422,"INVALID_QUALIFICATION_EVIDENCE");}
  long state=in.expectedStateVersion()+1;Boolean qualified=result.qualified();
  db.update("INSERT INTO card_month_states(user_id,card_id,month,current_qualified,version,source,qualification_source,qualification_as_of,qualification_period) VALUES(?,?,?,?,?,'USER_INPUT',?,?,?) ON CONFLICT(user_id,card_id,month) DO UPDATE SET current_qualified=EXCLUDED.current_qualified,version=EXCLUDED.version,qualification_source=EXCLUDED.qualification_source,qualification_as_of=EXCLUDED.qualification_as_of,qualification_period=EXCLUDED.qualification_period,updated_at=now()",u,c,m.atDay(1),qualified,state,qualified==null?"UNKNOWN":"USER_ESTIMATE",qualified==null?null:today,m.minusMonths(1).atDay(1));
  db.update("INSERT INTO actual_qualification_facts(user_id,card_id,month,previous_performance_won,previous_source,as_of,first_use_date,version,qualification_version,rule_version) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,card_id,month) DO UPDATE SET previous_performance_won=EXCLUDED.previous_performance_won,previous_source=EXCLUDED.previous_source,as_of=EXCLUDED.as_of,first_use_date=EXCLUDED.first_use_date,version=EXCLUDED.version,qualification_version=EXCLUDED.qualification_version,rule_version=EXCLUDED.rule_version,updated_at=now()",u,c,m.atDay(1),in.previousPerformanceWon(),in.previousSource(),in.asOf(),in.firstUseDate(),in.expectedVersion()+1,state,ActualQualification.VERSION);
  if(result.tier()!=null)db.update("INSERT INTO financial_benefit_months(user_id,card_id,month,tier,coverage_confirmed,qualification_version,version) VALUES(?,?,?,?,false,?,1) ON CONFLICT(user_id,card_id,month) DO UPDATE SET tier=EXCLUDED.tier,coverage_confirmed=false,qualification_version=EXCLUDED.qualification_version,version=financial_benefit_months.version+1,updated_at=now()",u,c,m.atDay(1),result.tier(),state);
  db.update("UPDATE app_users SET revision=revision+1 WHERE id=?",u);return get(u,c,period);
 }
}
